/** Real raw skill input / original pose and Garpai. Bounds and timing are
 * independent original byte facts, not snapshots generated by the SUT. */
import test from 'node:test';
import assert from 'node:assert/strict';
import {elesisFixture} from '../helpers/elesis-skill-fixture.mjs';
import * as shadow from '../../packages/combat-core/elesis-shadow-edge.mjs';
const {tickElesisShadowLinks,castElesisShadowEdge,validateElesisShadowLink}=shadow;
const links=s=>s.state.effects.filter(e=>e.sourceElesisShadowLink&&!e.dead);
function advance(s,n){for(let i=0;i<n;i++)s.step(1/60,{}, {snapshot:false});}
test('raw A cast directly creates explosion/link/buff at .31 when accepted contacts are unavailable',t=>{
 const s=elesisFixture('CA').make(28215),a=s.actor('elesis'),b=s.actor('target');
 t.mock.method(s,'checkHits',()=>0);
 s.step(1/60,{elesis:{pressed:['A'],held:['A']}},{snapshot:false});
 while(a.animationTime<.28)advance(s,1);
 assert.ok(a.animationTime<.31,'the sampled pre-query pose must actually precede the source threshold');
 assert.equal(links(s).length,0);assert.equal(b.buffs.some(v=>v.templateId===432),false);
 while(a.animationTime<.32)advance(s,1);
 assert.equal(links(s).length,1,'source query does not require projectile travel / accepted hit');
 const bip=s.effectAnchorSampler({definition:{BONE_NAME:'Bip01'}},a).position;
 assert.deepEqual(links(s)[0].currentAnchor.position,bip.map((v,i)=>v+(i===1?25:0)));
 assert.ok(b.buffs.some(v=>v.templateId===432));
 assert.equal(s.state.events.filter(e=>e.type==='hit').length,0);
 assert.ok(s.state.events.some(e=>e.type==='effectStarted'&&e.name==='DamageEffect_SCA_SHADOW_EDGE_Projectile_EXPLOSION'));
 assert.ok(!s.state.events.some(e=>e.type==='effectStarted'&&e.name==='DamageEffect_SCA_SHADOW_EDGE_Projectile'));
});
test('PvP query selects700 and link persists at900, then breaks beyond1200 with missing-bone fallback',t=>{
 const s=elesisFixture('CA').make(28215,'none',{distance:700}),a=s.actor('elesis'),b=s.actor('target');
 t.mock.method(s,'checkHits',()=>0);t.mock.method(s,'effectAnchorSampler',()=>null);
 s.step(1/60,{elesis:{pressed:['A'],held:['A']}},{snapshot:false});advance(s,23);
 const e=links(s)[0];assert.ok(e);
 for(const x of [700,900,1200]){b.x=a.x-x;b.y=a.y;b.z=a.z;tickElesisShadowLinks(s,.000001);assert.equal(e.dead,undefined);assert.equal(e.sourceElesisShadowLink.scale,x/530);}
 assert.deepEqual(e.currentAnchor.position,[a.x,a.y+100,a.z]);
 b.x=a.x-1200.1;tickElesisShadowLinks(s,.000001);assert.equal(e.dead,true);assert.ok(!b.buffs.some(v=>v.templateId===432));
});
test('source owner query never writes remote victim Buff; local victim still accepts real explosion',()=>{
 const s=elesisFixture('CA').make(28215);s.networkOwnerId='elesis';
 s.step(1/60,{elesis:{pressed:['A'],held:['A']}},{snapshot:false});advance(s,23);
 assert.equal(links(s).length,1);assert.ok(!s.actor('target').buffs.some(v=>v.templateId===432));
});
test('an unselected nearby AoE victim takes original explosion damage without acquiring a fourth link or slow',()=>{
 const s=elesisFixture('CA').make(28215),a=s.actor('elesis'),b=s.actor('target');
 s.step(1/60,{elesis:{pressed:['A'],held:['A']}},{snapshot:false});
 while(a.animationTime<.28)advance(s,1);
 b.x=a.x-690;
 const neighbour=structuredClone(b);neighbour.id='aoe-neighbour';neighbour.x=a.x-755;s.state.actors.push(neighbour);
 advance(s,12);
 assert.ok(s.state.events.some(e=>e.type==='hit'&&e.targetId===neighbour.id&&e.amount>0&&e.data.APPLIED_SKILL_ID===28215),'the outside-range neighbour must actually receive a positive explosion hit');
 assert.ok(neighbour.hp<neighbour.hpMax);
 assert.ok(!links(s).some(e=>e.sourceElesisShadowLink.targetId===neighbour.id));
 assert.ok(!neighbour.buffs.some(v=>v.templateId===432));
});
test('original pose at the1200 acquisition edge never exposes an invalid transient Link packet',t=>{
 const s=elesisFixture('CA').make(28215),a=s.actor('elesis'),b=s.actor('target'),preset=s.presetFor.bind(s);
 t.mock.method(s,'presetFor',actor=>({...preset(actor),gameMode:'NPC'}));t.mock.method(s,'checkHits',()=>0);
 s.step(1/60,{elesis:{pressed:['A'],held:['A']}},{snapshot:false});advance(s,22);
 Object.assign(a,{x:600,y:3080,z:0,lineId:2,lastTouchLineId:2});
 Object.assign(b,{x:-600,y:3080,z:0,lineId:2,lastTouchLineId:2});
 const from=s.effectAnchorSampler({definition:{BONE_NAME:'Bip01'}},a).position;
 const to=s.effectAnchorSampler({definition:{BONE_NAME:'Bip01'}},b).position;
 const sourceLength=Math.hypot(...to.map((v,i)=>v-from[i]));
 castElesisShadowEdge(s,a);
 const current=links(s);for(const e of current)validateElesisShadowLink(e,'CA',s.state.actors);
 assert.equal(current.length,sourceLength>1200?0:1);
 assert.equal(b.buffs.some(v=>v.templateId===432),sourceLength<=1200);
 console.log(JSON.stringify({originalPose1200:{sourceLength,liveLinks:current.length,atomicAdapter:sourceLength>1200}}));
});
